// Receives Sparrow webhook deliveries for webhook wh_cond.

import express from "express";
import type { Express, Request, Response } from "express";

import * as handlers from "./handlers.ts";
import { SignatureVerificationError, verifyHmac } from "./sparrow-verify.ts";

/** How far a delivery's webhook-timestamp may be from this server's clock before it is rejected as a possible replay. */
export const TOLERANCE_SECONDS = 300;

/** How many webhook-ids are remembered to drop redeliveries. 0 turns deduplication off. */
export const DEDUP_CAPACITY = 10000;

/** Caps the request body read before verification. */
export const MAX_BODY_BYTES = 10 * 1024 * 1024;

/** Answers a verified delivery no handler matches; a 4xx makes it fail visibly in Sparrow. */
export const UNKNOWN_EVENT_STATUS = 422;

export interface Config {
  /** The webhook's signing secret (whsec_...). Never commit it. */
  secret: string;
  /** Returns the current Unix time in seconds; defaults to the system clock. */
  now?: () => number;
  /** Gets one JSON line per handler call when set (SPARROW_RECEIVER_TEST_MODE=1 sets it to stdout). */
  testLog?: (line: string) => void;
}

export function configFromEnv(): Config {
  const testLog = process.env.SPARROW_RECEIVER_TEST_MODE === "1" ? (line: string) => process.stdout.write(line) : undefined;
  const secret = process.env.SPARROW_WEBHOOK_SECRET ?? "";
  if (!secret) {
    throw new Error("SPARROW_WEBHOOK_SECRET is not set");
  }
  return { secret, testLog };
}

/** The body does not match the handler's model; answered with 400. */
export class DecodeError extends Error {}

/**
 * In-memory LRU of seen webhook-ids. It is per process and lost on restart:
 * with several instances, use a shared store (your database) instead.
 */
class Dedup {
  private readonly items = new Map<string, true>();
  private readonly capacity: number;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  has(id: string): boolean {
    return this.items.has(id);
  }

  add(id: string): void {
    if (this.capacity <= 0 || !id) return;
    this.items.delete(id);
    this.items.set(id, true);
    while (this.items.size > this.capacity) {
      const oldest = this.items.keys().next().value;
      if (oldest === undefined) break;
      this.items.delete(oldest);
    }
  }
}

type Route = (body: Buffer, msgId: string) => Promise<void>;

export function createApp(config: Config): Express {
  const seen = new Dedup(DEDUP_CAPACITY);

  const record = (handler: string, subscriptionId: string, eventType: string, msgId: string, value: unknown): void => {
    config.testLog?.(
      JSON.stringify({ handler, subscription_id: subscriptionId, event_type: eventType, webhook_id: msgId, value }) + "\n",
    );
  };

  const parseJSON = (body: Buffer): unknown => {
    try {
      return JSON.parse(body.toString("utf8"));
    } catch (err) {
      throw new DecodeError(String(err));
    }
  };

  const routeOrderPaid: Route = async (body, msgId) => {
    const event = body.toString("utf8");
    record("handleOrderPaid", "sub_cond", "order.paid", msgId, event);
    await handlers.handleOrderPaid(event);
  };

  const bySubscription = new Map<string, Route>([
    ["sub_cond", routeOrderPaid],
  ]);
  const byEventType = new Map<string, Route>([
    ["order.paid", routeOrderPaid],
  ]);

  const app = express();
  app.disable("x-powered-by");

  app.get("/healthz", (_req: Request, res: Response) => {
    res.json({ status: "ok" });
  });

  // express.raw keeps the exact bytes: the signature covers them, whatever
  // the format.
  app.post("/webhook", express.raw({ type: () => true, limit: MAX_BODY_BYTES }), async (req: Request, res: Response) => {
    const body: Buffer = Buffer.isBuffer(req.body) ? req.body : Buffer.alloc(0);

    // 1. Verify the signature on the raw bytes, before any parsing. This
    // also rejects a webhook-timestamp outside TOLERANCE_SECONDS.
    try {
      verifyHmac(body, req.headers, config.secret, TOLERANCE_SECONDS, config.now?.());
    } catch (err) {
      if (err instanceof SignatureVerificationError) {
        res.status(401).json({ error: "invalid signature" });
        return;
      }
      throw err;
    }

    // 2. Drop redeliveries: webhook-id stays the same on every retry.
    const msgId = req.get("webhook-id") ?? "";
    if (seen.has(msgId)) {
      res.json({ status: "duplicate" });
      return;
    }

    // 3. Route on headers, never on the body: a transform can reshape it.
    const route =
      bySubscription.get(req.get("x-sparrow-subscription-id") ?? "") ??
      byEventType.get(req.get("x-sparrow-event-type") ?? "");
    if (!route) {
      res.status(UNKNOWN_EVENT_STATUS).json({ error: "no handler for this event" });
      return;
    }
    try {
      await route(body, msgId);
    } catch (err) {
      if (err instanceof DecodeError) {
        res.status(400).json({ error: `decode body: ${err.message}` });
        return;
      }
      console.error("handler failed", err);
      res.status(500).json({ error: "handler failed" });
      return;
    }
    // Remember the delivery only once it was handled, so a failed attempt is
    // processed again when Sparrow retries it.
    seen.add(msgId);

    // Answer fast: Sparrow waits for this response. Move slow work to a queue
    // and return 2xx as soon as it is accepted.
    res.json({ status: "ok" });
  });

  return app;
}
